const SKY93={"day": "data:image/jpeg;base64,", "morning": "data:image/jpeg;base64,", "night": "data:image/jpeg;base64,"};
function vpCiel(){const V=VP;if(!V||V.sky93)return;V.sky93={};const g=new THREE.SphereGeometry(Math.min(400,(V.cam.far||500)*.85),32,16);
 ['morning','day','night'].forEach((k,i)=>{const t=new THREE.TextureLoader().load(SKY93[k]);const m=new THREE.MeshBasicMaterial({map:t,side:THREE.BackSide,fog:false,transparent:true,opacity:k==='day'?1:0,depthWrite:false});const s=new THREE.Mesh(g,m);s.renderOrder=-10-i;V.sc.add(s);V.sky93[k]=s});
 if(V.sc.fog&&V.sc.fog.far)V.sc.fog.far=Math.max(V.sc.fog.far,110)}
{const vb=vpBoucle;vpBoucle=function(){vb.apply(this,arguments);try{const V=VP;if(!V||!V.p84)return;if(!V.sky93)vpCiel();const t=typeof TOD90==='function'?TOD90():.3,c=V.cam&&V.cam.position;
 const w={morning:t<.08?1-t/.08*.6:(t>.72&&t<.85?(t-.72)/.13:0),night:t>.85?Math.min(1,(t-.85)/.05):t<.04?1-t/.04:0};w.day=1;
 Object.keys(V.sky93).forEach(k=>{const s=V.sky93[k];if(c)s.position.copy(c);s.material.opacity=k==='day'?1:Math.max(0,Math.min(1,w[k]))})}catch(e){}}}
